Item.method_code:
const state = options.getState();
const itemId = state.grid.selectedRows[0];
const queryItem = window.currQryItem.getResult();
const itemNode =
	window.aras.getFromCache(itemId) ||
	queryItem.selectSingleNode(`Item[@id="${itemId}"]`);
if (!itemNode || window.execInTearOffWin(itemId, 'promote')) {
	return;
}

const itemKeyedName = window.aras.getKeyedNameEx(itemNode);
const dialogTitle = window.aras.getResource(
	'',
	'promotedlg.promote',
	itemKeyedName
);
const dialogResult = await window.parent.ArasCore.Dialogs.promote({ id: itemId, type: options.itemTypeName }, { title: dialogTitle });
if (!dialogResult || dialogResult.status === 'error') {
	return;
}

window.onSelectItem(dialogResult.id);
